import sympy as s
from math import factorial

def H(g,a,b=4): return {(-a-g+j):s.Integer(factorial(g))*s.binomial(-a,g-j)*s.binomial(a-b,j)*(-1)**j for j in range(g+1)}
def op(h,g,Q,sgn):
 # A_sgn=(1+x)(D+1+sgn*Q)-gx
 o={}
 for e,c in h.items():
  v=e+1+sgn*Q
  o[e]=o.get(e,0)+c*v
  o[e+1]=o.get(e+1,0)+c*(v-g)
 return {e:s.expand(c) for e,c in o.items() if c}
def col(g,q,a,br):
 Q=q+2; h=H(g,a)
 if br=='-': return op(h,g,Q,-1)
 return {e+Q:-c for e,c in op(h,g,Q,1).items()}
def audit(g,q,N,targets):
 labels=[(a,b) for a in range(N+1) for b in '-+']; cs=[col(g,q,*x) for x in labels]; rows=sorted(set().union(*[set(c) for c in cs])); M=s.Matrix([[c.get(e,0) for c in cs] for e in rows]); piv=[]; B=s.zeros(len(rows),0); r=0
 for j in range(M.cols):
  T=B.row_join(M[:,j]); nr=T.rank()
  if nr>r: piv.append(j);B=T;r=nr
 out=[]
 for a in targets:
  j=labels.index((a,'+')); sol=s.linsolve((B,M[:,j])); v=list(next(iter(sol))); mx=max(abs(x) for x in v); nz=sum(x!=0 for x in v); out.append((a,str(mx),nz))
 cap=[labels[j][0] for j in piv if labels[j][1]=='+']
 return cap,out
for g,q in [(6,3),(6,8),(6,13)]:
 cap,out=audit(g,q,25,[12,15,18,21,24]); print((g,q),'cap',cap,'deep',out)
